spec fn nonempty(a: &[i64]) -> bool { a.len() > 0 }

spec fn first_set(a: &[i64], b: &[i64], v: i64) -> bool { a.len() == b.len() && a[0] == v }

spec fn first_kept(a: &[i64], b: &[i64]) -> bool { a.len() == b.len() && a[0] == b[0] }

#[effects(pure)]
#[uses(nonempty, first_set, first_kept)]
fn set_first(a: &mut [i64], v: i64) -> ()
    requires nonempty(a),
    ensures first_set(a, old(a), v), first_kept(a, old(a)),
{
}

