#[summary("impossibility certificate")]
mod bmb_cert {
    spec fn never() -> bool { false }

    spec fn witness(a: &[i64], v: i64) -> bool { a.len() == 1 && a[0] != v }

    #[effects(pure)]
    #[uses(witness, tasks::nonempty, tasks::first_set, tasks::first_kept)]
    fn refute(a: &mut [i64], v: i64) -> ()
        requires witness(a, v),
        ensures never(),
    {
        tasks::set_first(a, v)
    }

    #[effects(pure)]
    #[uses(witness)]
    fn reach() -> () {
        let mut e: [i64; 1] = [0];
        refute(&mut e, 1)
    }
}

